window.__saqPaperQuestions("2015-1-pah",[{"number":1,"title":"","stemText":"SAQ Q 1\nA 48 year old man has been brought to the ED with chest pain and dizziness for the last 1\nhour.\nHis vital signs are:\n\nGCS\nE4 V4 M6\n\nBP\n80/45 mmHg O2 sats 99% 6L O2 via mask\n\nTemp\n36.5 degrees His ECG is shown below.","parts":[{"id":"a","label":"Part A","prompt":"What is your diagnosis of the rhythm displayed in the ECG? (1 mark)"},{"id":"b","label":"Part B","prompt":"List 3 supportive features from the ECG.\n(3 marks)"},{"id":"c","label":"Part C","prompt":"List 4 likely causes of this problem.\n(4 marks)"},{"id":"d","label":"Part D","prompt":"List 3 management steps you will undertake in the ED. Provide doses where\nappropriate. (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">VT</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Broad complex QRS</div><div class=\"answer-line\">Tachycardia rate approx 180</div><div class=\"answer-line\">Presence of capture beats</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Cardiac Ischaemia</div><div class=\"answer-line\">Electrolyte – hypokalaemia, hypomagenesemia</div><div class=\"answer-line\">Drug – eg tricyclics</div><div class=\"answer-line\">Primary arrhythmia</div><div class=\"answer-line\">Congenital</div><div class=\"answer-line\">Cardiomyopathies</div><div class=\"answer-line\">Infiltrative diseases</div><div class=\"answer-line\">(3 of 4 to pass)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Sedate – fentanyl 25mcg boluses, midazolam 0.5 – 1mg boluses</div><div class=\"answer-line\">Synchronized DC cardioversion – 100 – 200J</div><div class=\"answer-line\">Correct underlying cause</div><div class=\"answer-line\">Total pass 8/14 – corrects to<span class=\"answer-source-red\"> 5.5/10</span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 33 year old woman is being managed in your ED with severe community acquired\npneumonia. She is morbidly obese, with an estimated weight of 180kg and height of 160cm.\nHer vital signs are:\n\nGCS\nPulse 140 /min\n\nBP\n90/45 mmHg\n\nRR\n/min O2 sats 90% 15L/min O2 via non-rebreather mask\n\nTemp\n38.5 degrees The patient is becoming tired and you have assessed her as requiring intubation to maintain adequate oxygenation.","parts":[{"id":"a","label":"Part A","prompt":"In the section below, list 4 difficulties that you may encounter during the peri- intubation period. For each difficulty, briefly describe how you will aim to minimise the problem. (8 marks) Difficulty: Solution: Difficulty: Solution: Difficulty: Solution: Difficulty: Solution:"},{"id":"b","label":"Part B","prompt":"Give the ventilator settings you would initially institute by completing the table. (5 marks) YOUR SETTING\n\nFiO2\nRespiratory rate Tidal volume Positive end-expiratory pressure Peak pressure limit"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>YOUR SETTING</td><td></td></tr><tr><td>FiO2</td><td>1.0</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Respiratory rate</td><td>Something sensible – (14 – 25)</td></tr><tr><td>Tidal volume</td><td>Something sensible – (350 – 500 mL)</td></tr><tr><td>Positive end-expiratory pressure</td><td>5 – 10cmH2O</td></tr><tr><td>Peak pressure limit</td><td>35 – 40cmH2O</td></tr><tr><td colspan=\"2\">Pass 4/5</td></tr><tr><td colspan=\"2\">Total pass 10/13 corrects to <span class=\"answer-source-red\">7.5/10</span></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"SAQ Q 3\nA 75 year old man is brought to your ED with severe shortness of breath. You have assessed him to have an infective exacerbation of COPD. You are considering non-invasive ventilation (NIV) as part of his management.","parts":[{"id":"a","label":"Part A","prompt":"List 4 contra-indications to NIV for COPD in the ED.\n(2 marks) After one hour of bi-level NIV, an arterial blood gas is performed:\n\nFiO2\n0.5\n\npH\n7.26 mmHg (7.35 - 7.45)\n\npCO2\nmmHg (35 - 45)\n\npO2\nmmHg (60 - 100)\n\nHCO3\nmmol/L (24 - 34)\n\nBE\n7.1 mmol/L (-3 - 3) You note that this result is very similar to the arterial blood gas performed on arrival."},{"id":"b","label":"Part B","prompt":"List the pathological processes evident on the arterial blood gas, giving supportive evidence. (4 marks)"},{"id":"c","label":"Part C","prompt":"List the changes you would make to his NIV parameters as a result of the above findings. (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Decreased level consciousness</div><div class=\"answer-line\">Not initiating own breaths</div><div class=\"answer-line\">Vomiting</div><div class=\"answer-line\">Large haemoptysis</div><div class=\"answer-line\">Facial abnormalities</div><div class=\"answer-line\">Pt intolerance</div><div class=\"answer-line\">Not appropriate level of care</div><div class=\"answer-line\">** 3 of above to pass</div><div class=\"answer-line\">***nb change to 2 marks</div><div class=\"answer-line\">Each response ½ mark, pass 1.5/2</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Acute on chronic respiratory acidosis – raised CO2, acidaemia indicates acute, but pH not low</div><div class=\"answer-line\">enough for CO2 to be solely acute – therefore chronic process with chronic metabolic compensation</div><div class=\"answer-line\">Metabolic compensation – raised HCO3 and BE, chronic process</div><div class=\"answer-line\">2/4 to pass</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Increase iPAP - to increase TV and hence ventilation – to remove CO2</div><div class=\"answer-line\">Increase FiO2 or increase PEEP – to improve O2 (accept either but not both)</div><div class=\"answer-line\">2/2 to pass</div><div class=\"answer-line\">5.5/8 to pass corrects to <span class=\"answer-source-red\">6.5/10 </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"SAQ Q 4\nA 25 year old woman has been rushed in to your resuscitation room. She has just delivered\na baby in the passenger seat of a car being driven by her husband. The baby was 38 weeks gestation and appears to be well. The placenta was delivered in the car. The woman is experiencing heavy vaginal blood loss.","parts":[{"id":"a","label":"Part A","prompt":"In the section below, list 6 possible causes of her vaginal bleeding. For each cause give: -\n• ne cardinal finding of examination that would support that cause\n-\n• ne cardinal principle of management of that cause\n(18 marks)\nCause 1\nExamination Feature Management Principle\nCause 2\nExamination Feature Management Principle\nCause 3\nExamination Feature Management Principle\nCause 4\nExamination Feature Management Principle\nCause 5\nExamination Feature Management Principle\nCause 6\nExamination Feature Management Principle"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Examination visual inspection of perineum shows inverted uterus, fundus too low</td><td>Management uterine re-location - OT</td></tr><tr><td>Cause coagulopathy</td><td>Examination no other cause obvious, blood not clotting</td></tr><tr><td>Management correct coagulopathy with blood products</td><td>PASS 12/18 corrects to <span class=\"answer-source-red\">6.5/10 </span></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"SAQ Q 5\nA 19 year old man has presented to your rural ED after falling on to his out-stretched hand while playing basketball. He is complaining of wrist pain. There are no wounds visible. AP and lateral Xrays of his wrist are given.","parts":[{"id":"a","label":"Part A","prompt":"List the 2 main abnormalities shown on the Xrays.\n(2 marks)"},{"id":"b","label":"Part B","prompt":"List the 2 most serious possible immediate complications of this injury.\n(2 marks) You have elected perform a Bier’s block in your management of this injury."},{"id":"c","label":"Part C","prompt":"List the steps involved in performing a Bier’s block, including drugs, doses and end- points where appropriate. (6 marks)"}],"propPages":["asset:img1e6cbd29ccc16b78b0","asset:imgade319e6875633166a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Preparation – cardiac monitor, IV access *2 (one each arm – below fracture)</div><div class=\"answer-line\">Cuff – inflate to 100mmHg above systolic BP</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Pass Q3 – 3/6</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Q3 – ½ mark for concept, extra ½ mark for specifics</div><div class=\"answer-line\">Pass Q3 – 3/6</div><div class=\"answer-line\">Total pass – <span class=\"answer-source-red\">7/10  </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"SAQ Q 6\nA 56 year old man has been brought to your tertiary ED after a motorcycle accident.\nHis pelvic Xray is given.","parts":[{"id":"a","label":"Part A","prompt":"Classify his pelvic injury based on the Xray provided. (2 marks)"},{"id":"b","label":"Part B","prompt":"List 4 possible methods of arresting the blood loss from his pelvic injury.\n(4 marks) CT scans have revealed active arterial haemorrhage related to his pelvic injury, but no other\n• bvious injuries.\nHis vital signs are:\n\nGCS\nE4 V4 M6 Pulse 135 /min\n\nBP\n70/40 mmHg O2 saturation 98% 6L O2 via mask\n\nTemp\n36.5 degrees"},{"id":"c","label":"Part C","prompt":"In point form, list your principles of his fluid resuscitation while he is awaiting definitive management of his pelvic injury. (5 marks)"}],"propPages":["asset:img8797cd8981ec93c117"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Pass 1</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Pass any 3 out of 4</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Targets: systolic BP 80mmHg, radial pulse, mentation</div><div class=\"answer-line\">Use blood products, minimal crystalloid</div><div class=\"answer-line\">Initially O neg then Xmatched</div><div class=\"answer-line\">Initiate massive transfusion protocol early</div><div class=\"answer-line\">Aim packed cells:FFP:platelets 1:1:1 ratio</div><div class=\"answer-line\">(targeted to ROTEM acceptable)</div><div class=\"answer-line\">Each point 1 mark but has to show clinical reasoning</div><div class=\"answer-line\">Pass 3/5</div><div class=\"answer-line\">Total pass 7/11 corrects to <span class=\"answer-source-red\">6/10</span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"SAQ Q 7\nA 4 year old girl has been brought to your ED with an exacerbation of asthma.","parts":[{"id":"a","label":"Part A","prompt":"List 6 features of your examination that would lead to you concluding that this\nexacerbation is life-threatening in severity. (6 marks) You have assessed the girl to be experiencing a life-threatening exacerbation of asthma."},{"id":"b","label":"Part B","prompt":"List 5 treatments you would use including doses.\n(5 marks)"},{"id":"c","label":"Part C","prompt":"List the drugs you would use to facilitate intubation if necessary. Include doses. (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Marked increased work breathing</div><div class=\"answer-line\">Silent chest</div><div class=\"answer-line\">Inability to talk</div><div class=\"answer-line\">Tachypnoea</div><div class=\"answer-line\">Tachycardia</div><div class=\"answer-line\">Hypotension</div><div class=\"answer-line\">Hypoxia</div><div class=\"answer-line\">Pass 5/6</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Salbutamol nebs 2.5 - 5mg continuous</div><div class=\"answer-line\">Ipratropium 250mcg times 3 nebs in first hour</div><div class=\"answer-line\">Steroid IV – methypred 1mg/kg or hydrocortisone 4mg/kg</div><div class=\"answer-line\">Salbutamol IV – 5-10mcg/kg bolus then infusion</div><div class=\"answer-line\">Also accept MgSO4 – 50mg/kg bolus then infusion</div><div class=\"answer-line\">Also accept aminophylline – 10mg/kg loading dose</div><div class=\"answer-line\">1 mark for complete treatment with correct dose</div><div class=\"answer-line\">Pass 3/5</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Sux 1-2mg/kg</div><div class=\"answer-line\">Also accept other variations that seem sensible</div><div class=\"answer-line\">Pass 2/2</div><div class=\"answer-line\">Total pass 10/13 corrects to <span class=\"answer-source-red\">7.5/10</span><span class=\"answer-source-red\"> </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"SAQ Q 8\nA 2 year old girl has been brought to your ED with a rash. She has been unwell with fever\nfor 5 days. She had been seen by her local doctor 2 days ago.\nHer rash is shown in the clinical image below.","parts":[{"id":"a","label":"Part A","prompt":"In point form, describe the image. (4 marks)"},{"id":"b","label":"Part B","prompt":"Give your diagnosis for the rash. (2 marks)"},{"id":"c","label":"Part C","prompt":"List the 2 most common aetiological groups responsible for this rash, and 4 specific\nagents in each group. (6 marks) Group Specific agent"}],"propPages":["asset:img7dc61d6620f19ef227"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Multiple lesions of different sizes</div><div class=\"answer-line\">Discrete lesions, no confluence</div><div class=\"answer-line\">Erythematous macules</div><div class=\"answer-line\">Target lesions with central clearing (CRITICAL TO PASS)</div><div class=\"answer-line\">Distribution over anterior right arm and forearm and anterior right side of thorax shown</div><div class=\"answer-line\">Child appears well perfused</div><div class=\"answer-line\">Pass 3 out of 4</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Erythema multiforme</div><div class=\"answer-line\">Pass 2</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Drugs – sulphur antibiotics, anticonvulsants, NSAIDs, cephalosporins</div><div class=\"answer-line\">Infectious – mycoplasma, HSV, other viruses eg EBV, fungal infections</div><div class=\"answer-line\">(no other groups acceptable)</div><div class=\"answer-line\">Mark out of 6 not 8</div><div class=\"answer-line\">1 mark for each group with ½ mark for each agent</div><div class=\"answer-line\">Pass  3 of 6</div><div class=\"answer-line\">Total pass 8/12 corrects to <span class=\"answer-source-red\">6.5/10</span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"SAQ Q 9\nThe ambulance service has brought a 23 year old man to your ED. He was found wandering the streets naked. He became aggressive while being transported to hospital. On arrival to the triage desk, he is swearing loudly and trying to leave. He is known to have a history of schizophrenia and drug use.","parts":[{"id":"a","label":"Part A","prompt":"Give the 2 legislative principles of care that might allow you to keep this man against his will. For each principle of care, list 2 main conditions that must be met. (6 marks) Legislative Principle Conditions that must be met"},{"id":"b","label":"Part B","prompt":"List 5 main steps in restraint of this man, in escalating order. Where appropriate, give\ninitial doses of medications. (5 marks) During the management of this patient, one of your junior doctors has received a needle-stick injury from a hollow-bore needle used on the patient."},{"id":"c","label":"Part C","prompt":"Complete the table about risk of transmissible disease in this scenario. (3 marks) SOURCE - known to have disease Risk of transmission Hepatitis B Hepatitis C HIV"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Duty of care</td><td></td></tr><tr><td>-</td><td>Have a physical condition causing behavioural disturbance</td></tr><tr><td>-</td><td>Be at risk to himself or others</td></tr><tr><td>Mental Health Act</td><td></td></tr><tr><td>-</td><td>Suspected mental health disorder</td></tr><tr><td>-</td><td>No less restrictive means available</td></tr><tr><td>1 mark for each principle, 1 mark for each condition</td><td></td></tr><tr><td>Pass 4/6</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Verbal de-escalation</div><div class=\"answer-line\">Oral sedation eg diazepam 10mg</div><div class=\"answer-line\">Show of force</div><div class=\"answer-line\">Physical restraint – isolation or with manual handling</div><div class=\"answer-line\">Chemical restraint eg droperidol 10mg</div><div class=\"answer-line\">Pass 3 of 5</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Hep B  30-60%</div><div class=\"answer-line\">Hep C  3%</div><div class=\"answer-line\">HIV</div><div class=\"answer-line\">0.3%</div><div class=\"answer-line\">(accept answers that are close)</div><div class=\"answer-line\">Pass 2 of 3</div><div class=\"answer-line\">Total pass 9/14 corrects to <span class=\"answer-source-red\">6/10 </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"SAQ Q 10\nYou are the director of your Emergency Department. The mother of a 4 year old boy has rung to complain about the treatment her son received in your ED. The boy was seen in your ED the day prior with abdominal pain and sent home. Due to ongoing pain, he was taken to another hospital where the diagnosis of testicular torsion was made. At surgical exploration, the testis was found to be non-viable.","parts":[{"id":"a","label":"Part A","prompt":"List 4 points that you would convey to the mother during your conversation\n(4 marks)"},{"id":"b","label":"Part B","prompt":"List 5 important aspects in your management of this situation\n(5 marks)"},{"id":"c","label":"Part C","prompt":"List 6 possible causes for this situation\n(6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Accept complaint</div><div class=\"answer-line\">Apologize for inconvenience</div><div class=\"answer-line\">Undertake to investigate</div><div class=\"answer-line\">Assure mother she will get response</div><div class=\"answer-line\">(other responses may be acceptable)</div><div class=\"answer-line\">Pass 2 of 4</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Recall / review chart</div><div class=\"answer-line\">Discuss with treating doctor</div><div class=\"answer-line\">Inform medico-legal team institution</div><div class=\"answer-line\">Medico-legal for treating practitioner</div><div class=\"answer-line\">Identify problems causing missed diagnosis</div><div class=\"answer-line\">Implement changes to prevent further similar problems</div><div class=\"answer-line\">(quality improvement cycle)</div><div class=\"answer-line\">(accept other reasonable responses)</div><div class=\"answer-line\">Pass 3 of 5</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Pt factors – unusual presentation</div><div class=\"answer-line\">Staff factors</div><div class=\"answer-line\">Lack of knowledge</div><div class=\"answer-line\">Lack of experience</div><div class=\"answer-line\">Lack of supervision</div><div class=\"answer-line\">Process factors</div><div class=\"answer-line\">Understaffed</div><div class=\"answer-line\">Busy shift</div><div class=\"answer-line\">Lack of protocols surrounding discharge by junior doctor</div><div class=\"answer-line\">(accept other reasonable responses)</div><div class=\"answer-line\">Pass 3 of 6</div><div class=\"answer-line\">Total pass 8 of 15 corrects to <span class=\"answer-source-red\">5/10 </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"SAQ Q 11\nA 5 year old boy has been brought to your ED with a 2 day history of fever, cough and lethargy. He has the following vital signs:\n\nTemp\n38.8 degrees Pulse 145 /min\n\nBP\n90/40 mmHg\n\nRR\n/min O2 sats 91% room air Examination of his chest reveals decreased breath sounds and crackles in the right lung base. He has had a venous blood gas taken:\n\npH\n7.18 (7.35 - 7.45)\n\npCO2\nmmHg (35 - 45)\n\npO2\nmmHg (80 - 100)\n\nHCO3-\nmmol/L (22 - 32)\n\nBE\n-18.5 mmol/L (-3 - +3)\n\nNa\n140 mmol/L (135 - 145)\n\nK\n5.7 mmol/L (3.5 - 5.0)\n\nCl\nmmol/L (100 - 110)\n\nGlucose\nmmol/L (3.0 - 7.8)","parts":[{"id":"a","label":"Part A","prompt":"In point form, provide explanation for all the abnormalities shown on the VBG. (8 marks)"},{"id":"b","label":"Part B","prompt":"What is your diagnosis, based on all the clinical information? (2 marks)"},{"id":"c","label":"Part C","prompt":"List your 5 main treatment steps, with drugs and doses where appropriate.\n(5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Moderately severe acidaemia – pH decreased 7.18</div><div class=\"answer-line\">Metabolic acidosis – reduced HCO3 and BE</div><div class=\"answer-line\">High anion gap 34 – Diabetic ketoacidosis, other possible causes renal failure, lactic acidosis</div><div class=\"answer-line\">Appropriate respiratory compensation – pCO2 reduced</div><div class=\"answer-line\">Na corrected for glucose is approx. 151 – elevated suggesting total body water loss / dehydration</div><div class=\"answer-line\">K is elevated but when corrected for pH is likely to be approx. 4.7 which is in normal range</div><div class=\"answer-line\">Cl reduced to maintain electrical neutrality in face of excess anions</div><div class=\"answer-line\">Glucose elevated in DKA</div><div class=\"answer-line\">Pass 6 of 8</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Diabetic ketoacidosis exacerbated by pneumonia</div><div class=\"answer-line\">Pass 2 of 2</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Insulin infusion 0.1U/kg/hr</div><div class=\"answer-line\">IV fluid – initial bolus 20ml/kg N/S, then replace deficit plus maintenance over 24hrs</div><div class=\"answer-line\">IV antibiotics – benzylpenicillin 60mg/kg and roxithromycin 4mg/kg</div><div class=\"answer-line\">K replacement – add 20-40mmol/L to fluids when K below 4.5 -5.0</div><div class=\"answer-line\">Dextrose – add 5% dextrose to N/S when glucose below 12-15</div><div class=\"answer-line\">(must have</div><div class=\"answer-line\">Pass 3 of 5</div><div class=\"answer-line\">Total Pass 11/15 corrects to <span class=\"answer-source-red\">7/10 </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"SAQ Q 12\nA 35 year old woman has been brought to your hospital by ambulance. Her husband arrived home to find her unconscious on her bed. She had written a suicide note. An overdose is suspected, although no empty medication packets could be found.\nHer vital signs are:\n\nGCS\n(E1 V2 M5)\n\nBP\n75/45 mmHg O2 sats 99% 15L O2 via non-rebreather\n\nTemp\n36.0 degrees An ECG is performed.","parts":[{"id":"a","label":"Part A","prompt":"List the main abnormalities on the ECG (3 marks)"},{"id":"b","label":"Part B","prompt":"What group of drugs most commonly give this clinical picture? (1 mark) After a brief period, the patient begins to have a generalised seizure."},{"id":"c","label":"Part C","prompt":"List your initial management steps, including drugs, doses and end-points where appropriate. (10 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Broad QRS – between 160-200ms (CRITICAL)</div><div class=\"answer-line\">Terminal right axis deviation of QRS</div><div class=\"answer-line\">Absolute QT prolonged about 480ms</div><div class=\"answer-line\">Pass 2 of 3</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Tri-cyclic anti-depressants</div><div class=\"answer-line\">Pass 1</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Terminate seizure</div><div class=\"answer-line\">– midazolam 2.5mg aliquots</div><div class=\"answer-line\">Serum alkalinisation aiming for pH 7.5 (2 steps below so 4 marks)</div><div class=\"answer-line\">Intubate</div><div class=\"answer-line\">o – ketamine 100mg, rocuronium 100mg</div><div class=\"answer-line\">IV HCO3</div><div class=\"answer-line\">o – initial bolus 100mmol</div><div class=\"answer-line\">IV N/S bolus</div><div class=\"answer-line\">– 1000mL repeat if needed, for systolic BP &gt;90mmHg (MAP &gt;65mmHg)</div><div class=\"answer-line\">Noradrenaline infusion if needed for BP goal</div><div class=\"answer-line\">(3% saline if refractory hypotension, aiming for Na 150)</div><div class=\"answer-line\">1 mark for each concept, 1 mark for action details</div><div class=\"answer-line\">Pass 6 of 10</div><div class=\"answer-line\">Total pass 9/14 corrects to <span class=\"answer-source-red\">6/10 </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"SAQ Q 13\nA 29 year old man has been brought to your hospital after being hit to the head by a baseball bat. He has no prior medical history.\nHis vital signs on arrival to the ED are:\n\nGCS\nE2 V2 M5 Pulse 110 /min\n\nBP\n110/65 mmHg O2 sats 99% 6L O2 via mask A CT scan of his head has been performed.","parts":[{"id":"a","label":"Part A","prompt":"List 5 abnormalities on the CT slice.\n(5 marks)"},{"id":"b","label":"Part B","prompt":"List your treatment priorities in the ED. Where appropriate, give end-points. (9 marks)"}],"propPages":["asset:img08992f829f230cc79f"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Large extradural haematoma – high density bi convex lesion left temporal region</div><div class=\"answer-line\">Hyperacute extradural with “swirl sign” mixed density</div><div class=\"answer-line\">Large scalp haematoma left temporal region</div><div class=\"answer-line\">Parietal cerebral contusion left</div><div class=\"answer-line\">Significant midline shift to right</div><div class=\"answer-line\">Loss of sulci and gyri consistent with raised intracranial pressure</div><div class=\"answer-line\">Pass 3 of 5</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Immediate neurosurgical referral for surgical drainage of haematoma</div><div class=\"answer-line\">Intubation for airway control and management of CO2</div><div class=\"answer-line\">Maintain MAP &gt;80 (accept approx.) mmHg with IV N/S +/- noradrenaline infusion</div><div class=\"answer-line\">Maintain oxygenation sats &gt;95%</div><div class=\"answer-line\">Ventilate for low normal CO2 (35 – 40)</div><div class=\"answer-line\">Other neuroprotective measures (max 4 marks)</div><div class=\"answer-line\">Well sedated, paralysed</div><div class=\"answer-line\">Slightly head-up position</div><div class=\"answer-line\">Loosen ties / restriction to venous return</div><div class=\"answer-line\">Na high normal range</div><div class=\"answer-line\">Normothermia</div><div class=\"answer-line\">normoglycaemia</div><div class=\"answer-line\">pass 5 of 9</div><div class=\"answer-line\">total pass 8 of 14 corrects to <span class=\"answer-source-red\">5.5/10 </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"SAQ Q 14\nA 62 year old lady presents with difficulty breathing after eating dinner. She has a history of ischaemic heart disease. On arrival, her vital signs are:\n\nGCS\nPulse 130 /min\n\nBP\n85/45 mmHg O2 sats 98% room air Her photo is reproduced:","parts":[{"id":"a","label":"Part A","prompt":"Briefly describe 2 abnormalities in the photo.\n(2 marks)"},{"id":"b","label":"Part B","prompt":"What is your clinical interpretation of the information given? (2 marks)"},{"id":"c","label":"Part C","prompt":"List 3 signs of impending airway obstruction in this patient.\n(3 marks) You have assessed the patient as not requiring immediate airway management."},{"id":"d","label":"Part D","prompt":"List your 2 main treatment steps. Give doses and endpoints.\n(4 marks)"}],"propPages":["asset:img93e55c0cdbcab2b04f"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">- severe tongue oedema occupying most of mouth, with tongue protrusion</div><div class=\"answer-line\">- oedema and erythema peri-orbital regions</div><div class=\"answer-line\">- pt looks pale</div><div class=\"answer-line\">Pass 1 of 2</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">- anaphylaxis</div><div class=\"answer-line\">Angio-oedema of tongue causing threatened airway</div><div class=\"answer-line\">Cardiovascular compromise</div><div class=\"answer-line\">Pass 2 of 2</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Stridor</div><div class=\"answer-line\">Hypoxia / cyanosis</div><div class=\"answer-line\">Increased work of breathing</div><div class=\"answer-line\">Fatigue (decreased GCS)</div><div class=\"answer-line\">Pass 2 of 3</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">IV fluid</div><div class=\"answer-line\">Normal saline 1L bolus (20mL/kg) repeat if needed, aiming for systolic &gt;90mmHg or MAP</div><div class=\"answer-line\">&gt;65mmHg</div><div class=\"answer-line\">Adrenaline</div><div class=\"answer-line\">Stat IM 500mcg, repeat Q 5min if needed</div><div class=\"answer-line\">If deteriorating, IV boluses 50mcg</div><div class=\"answer-line\">Infusion start at 5-10mcg/min</div><div class=\"answer-line\">Aiming for – systolic as above, reduction in angio-oedema</div><div class=\"answer-line\">1 mark for concept, 1 mark for details</div><div class=\"answer-line\">Pass 3 of 4</div><div class=\"answer-line\">Total pass 8/11 corrects to <span class=\"answer-source-red\">7/10 </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"SAQ Q 15\nA young mother has just delivered a baby in your resuscitation cubicle. She was estimated to be 36 weeks gestation. There was no meconium staining of the amniotic fluid. You are tasked with managing the child.","parts":[{"id":"a","label":"Part A","prompt":"What are the 3 initial assessment features in neonatal resuscitation?\n(3 marks) The child is not breathing."},{"id":"b","label":"Part B","prompt":"What is your initial action? (1 mark)"},{"id":"c","label":"Part C","prompt":"List 4 additional actions you may perform during the resuscitation of this child. For each, give the indication. (8 marks) Action Indication"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Tone</div><div class=\"answer-line\">Breathing</div><div class=\"answer-line\">Heart rate</div><div class=\"answer-line\">Pass 3 of 3</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Stimulation</div><div class=\"answer-line\">No pass</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>BVM – if not breathing after stimulation</td><td>CPR – if HR less than 60 despite initial BVM</td></tr><tr><td>Intubation – prolonged CPR</td><td>Adrenaline 10-30mcg/kg – ongoing HR &lt;60 despite BVM and initial CPR</td></tr><tr><td>IV fluid – 10mL/kg – ongoing HR &lt;60 despite BVM and CPR</td><td>(accept some form of IV/IO access)</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"SAQ Q 16\nA 75 year old man has been brought to the ED with abdominal pain. He has come from a nursing home. His background history includes dementia and ischaemic heart disease. An Xray has been performed:","parts":[{"id":"a","label":"Part A","prompt":"Give your diagnosis/diagnoses with supportive Xray findings. (4 marks)"},{"id":"b","label":"Part B","prompt":"List 3 specific treatment options for this patient’s problem.\n(3 marks)"},{"id":"c","label":"Part C","prompt":"List 2 features of your supportive treatment. Include doses and end-points.\n(4 marks)"},{"id":"d","label":"Part D","prompt":"List 3 important considerations in determining your ceiling of care.\n(3 marks)"}],"propPages":["asset:imgd2706b7fbeea47fe60"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Sigmoid volvulus – massively dilated loop of sigmoid colon with axis pointing to LIF (CRITICAL)</div><div class=\"answer-line\">LBO – dilated large bowel proximal to volvulus with no gas distal (ie rectum)</div><div class=\"answer-line\">1 mark for each diagnosis, 1 mark for explanation</div><div class=\"answer-line\">Pass 2of 4</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Per rectal tube decompression</div><div class=\"answer-line\">Laparotomy</div><div class=\"answer-line\">Conservative (ie no management)</div><div class=\"answer-line\">Percutaneous drainage initially</div><div class=\"answer-line\">Pass 2 of 3</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia – IV opiate morphine 1-2mg aliquots, fentanyl 10-20mcg aliquots</div><div class=\"answer-line\">IV fluid – N/S 20ml/kg boluses to correct shock then maintenance fluid titrated tom UO</div><div class=\"answer-line\">Communication – explanation to pt/ substitute decision maker</div><div class=\"answer-line\">1 for each concept 1 for explanation</div><div class=\"answer-line\">Pass 2 of 4</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Pt competence to make decisions</div><div class=\"answer-line\">Presence of advanced health directive</div><div class=\"answer-line\">NOK wishes if pt not competent</div><div class=\"answer-line\">Baseline level of function</div><div class=\"answer-line\">Pass 2 of 3</div><div class=\"answer-line\">Total pass 8/14 corrects to <span class=\"answer-source-red\">5.5/10 </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"SAQ Q 17\nA 45 year old man has been brought to your ED by ambulance after being stabbed once in the right side of the chest. On arrival, his vital signs are:\n\nGCS\nE4 V4 M6 Pulse 120 /min\n\nBP\n85/40 mmHg O2 sats 94% 15L O2 via non-rebreather mask A chest Xray has been performed.","parts":[{"id":"a","label":"Part A","prompt":"Give the main abnormality on the chest Xray, with supporting evidence. (3 marks)"},{"id":"b","label":"Part B","prompt":"List the steps involved in inserting an intercostal catheter in this patient. (9 marks)"}],"propPages":["asset:img5bb20e28f28365954c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Right sided tension haemothorax (CRITICAL)</td></tr><tr><td>-</td><td>Veiled opacity to right hemi-thorax</td></tr><tr><td>-</td><td>Significant rim of fluid around lateral lung edge</td></tr><tr><td>-</td><td>Mediastinal shift to left</td></tr><tr><td colspan=\"2\">1 mark for haemothorax, ½ marks for – tension, 3 other bits</td></tr><tr><td colspan=\"2\">pass 2 of 3</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Verbal consent / explanation</div><div class=\"answer-line\">(sedation optional)</div><div class=\"answer-line\">(Gown / gloves / mask / goggles)</div><div class=\"answer-line\">Clean chest with anti-septic (appreciate this is a time critical procedure)</div><div class=\"answer-line\">Local anaesthesia – lignocaine 1% with adrenaline 20mL</div><div class=\"answer-line\">Location  - 5th interspace mid-axillary line</div><div class=\"answer-line\">Incision with scalpel</div><div class=\"answer-line\">Blunt dissection to pleural space / finger sweep</div><div class=\"answer-line\">Insertion ICC 28-32 Fr</div><div class=\"answer-line\">Connection to underwater seal</div><div class=\"answer-line\">Suture and dressing</div><div class=\"answer-line\">Pass 7 of 9</div><div class=\"answer-line\">Total pass 9/12 corrects to <span class=\"answer-source-red\">7.5/10 </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"SAQ Q 18\nA 50 year old man presents to your ED with palpitations.\nOn examination, you have found him to be in atrial fibrillation with a rapid ventricular rate.","parts":[{"id":"a","label":"Part A","prompt":"List your criteria for consideration of this man for cardioversion in the ED. (4 marks)"},{"id":"b","label":"Part B","prompt":"List 2 drugs you could use for chemical cardioversion. For each drug, give the dose and 2\ncontra-indications. (8 marks) Drug Dose Contra-indications"},{"id":"c","label":"Part C","prompt":"List 3 drugs you could use intravenously for rate control. For each drug, give the dose.\n(6 marks)"},{"id":"d","label":"Part D","prompt":"How would you assess this man’s risk of thrombo-embolism? (1 mark)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Haemodynamic instability</div><div class=\"answer-line\">Definite onset AF within 24-48 hours</div><div class=\"answer-line\">Lack of known structural heart disease</div><div class=\"answer-line\">Non-chronic AF</div><div class=\"answer-line\">Correctable or no clear precipitant</div><div class=\"answer-line\">Pt preference</div><div class=\"answer-line\">Pass 2 of 4</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Flecainide 2mg/kg – known LV dysfunction, intra-ventricular blocks (eg BBBs)</td><td>Amiodarone 300mg – iodine allergy, hypotension, thyroid dysfunction, long QT</td></tr><tr><td>Sotalol 40 – 80mg – long QT, asthma, hypotension</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Metoprolol 2mg aliquots ,max 20mg</td><td>Verapamil 2.5-5mg aliquots, max 20mg</td></tr><tr><td>Digoxin initial loading dose 500mcg</td><td>1 mark for drug, 1 mark for dose</td></tr><tr><td>Pass 4 of 6</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Either CHADS2 or CHA2DS2-Vasc score</div><div class=\"answer-line\">No pass</div><div class=\"answer-line\">Total pass 11/19 corrects to <span class=\"answer-source-red\">5.5/10</span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"SAQ Q 19\nA 23 year old man has been brought to your ED after having a seizure at a dance party. He has no known medical history. On arrival, his vital signs are:\n\nGCS\nE 2 V 2 M 4\nPulse 120 /min\n\nBP\n110/70 mmHg\n\nTemp\n41.0 degrees O2 sats 100% 6L O2 via mask","parts":[{"id":"a","label":"Part A","prompt":"List 3 possible non-toxicological causes of this presentation.\n(3 marks)"},{"id":"b","label":"Part B","prompt":"List 3 possible toxicological causes of this presentation. For each, give 3 cardinal\nexamination features that would suggest the diagnosis. (12 marks) Cause Cardinal examination findings"},{"id":"c","label":"Part C","prompt":"List 4 methods of cooling appropriate for this patient.\n(4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Heat stroke (exposure)</div><div class=\"answer-line\">Sepsis – meningitis</div><div class=\"answer-line\">Hyperthyroidism</div><div class=\"answer-line\">(DDx must address severe hyperthermia)</div><div class=\"answer-line\">Pass 2 of 3</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Serotonin toxicity – hyper-reflexia, muscular rigidity, mydriasis etc</td><td>Anti-cholinergic syndrome – dry skin, flushed, mydriasis, delirium etc</td></tr><tr><td>Sympathomimetic toxicity – tachycardia, dilated pupils, hypertension etc</td><td>Neuroleptic malignant syndrome – rigidity, hypertension, CNS</td></tr><tr><td>1 mark for causes, 1 mark for each finding</td><td>Pass 7 of 12</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Remove clothing</div><div class=\"answer-line\">Fans with mist</div><div class=\"answer-line\">Ice packs to axillae / groins / neck</div><div class=\"answer-line\">Cold IV fluids – 4 degrees N/S</div><div class=\"answer-line\">Cold bladder irrigation</div><div class=\"answer-line\">Pass 3 of 4</div><div class=\"answer-line\">Total pass 12/19 corrects to <span class=\"answer-source-red\">6/10 </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"SAQ Q 20\nA 65 year old man has presented to the ED with a painful left eye. The pain developed over 30 minutes while he was at the movie theatre. A clinical photo of his right eye is given.","parts":[{"id":"a","label":"Part A","prompt":"List 3 abnormalities in the clinical photo.\n(3 marks)"},{"id":"b","label":"Part B","prompt":"Give your clinical impression of the photo. (2 marks)"},{"id":"c","label":"Part C","prompt":"List 3 specific treatment steps for this patient.\n(3 marks)"},{"id":"d","label":"Part D","prompt":"List 2 supportive treatment steps for this patient.\n(2 marks)"}],"propPages":["asset:img226653a1b7086a49b5"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Cloudy cornea</div><div class=\"answer-line\">Mid-sized pupil</div><div class=\"answer-line\">Ciliary injection, especially laterally</div><div class=\"answer-line\">Pass 2 of 3</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Acute angle closure glaucoma</div><div class=\"answer-line\">Pass 2 of 2</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Early ophthalmological review - laser</div><div class=\"answer-line\">IV acetazolamide</div><div class=\"answer-line\">Topical pilocarpine to constrict pupil</div><div class=\"answer-line\">Topical apraclonidine</div><div class=\"answer-line\">Topical beta blocker</div><div class=\"answer-line\">Pass 2 of 3</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Analgesia</div><div class=\"answer-line\">Anti-emetic</div><div class=\"answer-line\">Pass 1 of 2</div><div class=\"answer-line\">Total pass <span class=\"answer-source-red\">7/10 </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"SAQ Q 21\nA 45 year old man has presented to the ED with cough of 2 weeks duration.\nHis chest Xray is given below.","parts":[{"id":"a","label":"Part A","prompt":"Describe the main abnormality on the chest Xray. (2 marks)"},{"id":"b","label":"Part B","prompt":"List 3 relevant negatives on review of the chest Xray.\n(3 marks)"},{"id":"c","label":"Part C","prompt":"List 3 groups of pathological causes for this abnormality. For each, give 2 aetiological agents. (6 marks) Aetiological agent Pathological cause"}],"propPages":["asset:img83388935804ff0e870"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Solitary lesion left upper zone</td></tr><tr><td>-</td><td>Round / oval shaped</td></tr><tr><td>-</td><td>Has a defined wall / discrete lesion</td></tr><tr><td>-</td><td>Contains air/fluid level</td></tr><tr><td colspan=\"2\">= cavitating lesion (1 mark)</td></tr><tr><td colspan=\"2\">½ mark for others</td></tr><tr><td colspan=\"2\">Pass 1.5 of 2</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">No surrounding consolidation</div><div class=\"answer-line\">No evidence chronic lung disease</div><div class=\"answer-line\">No hilar lymphadenopathy obvious</div><div class=\"answer-line\">No pneumothorax</div><div class=\"answer-line\">No effusion</div><div class=\"answer-line\">Pass 2 of 3</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Infection/abscess – bacterial (Strep / Staph / Gram neg), fungal, TB</td><td>Malignancy – primary bronchogenic, metastasis</td></tr><tr><td>Granuloma – rheumatoid,  Wegeners</td><td>Infarction – trauma, PE</td></tr><tr><td>1 mark for each cause, ½ mark for each agent</td><td>Pass 3 of 6</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"SAQ Q 22\nA 55 year old woman has been referred to the ED by her GP with a 2 day history of bilateral leg weakness. Her GP suspects Guillain-Barre syndrome.","parts":[{"id":"a","label":"Part A","prompt":"List 6 differential diagnoses for this patient’s weakness. (Do not include GBS)\n(6 marks)"},{"id":"b","label":"Part B","prompt":"List 3 cardinal features on examination you would expect to find that would be consistent\nwith classical Guillain-Barre syndrome. (3 marks)"},{"id":"c","label":"Part C","prompt":"List 3 investigations that will be useful in supporting the diagnosis of GBS. Include the\nexpected findings. (6 marks)"},{"id":"d","label":"Part D","prompt":"List 2 life-threatening complications of GBS. For each complication, mention how you will\ndetect its presence or severity. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Spinal cord compression / cauda equine compression  – tumour, abscess, haematoma</div><div class=\"answer-line\">Transverse myelitis</div><div class=\"answer-line\">Traumatic spinal cord injury</div><div class=\"answer-line\">Spinal cord infarct – embolic/thrombotic</div><div class=\"answer-line\">Myopathies – eg myasthenia gravis</div><div class=\"answer-line\">Electrolyte – hypoK periodic paralysis</div><div class=\"answer-line\">Toxins – tick paralysis, botulism</div><div class=\"answer-line\">Pass 4 of 6</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Symmetrical ascending weakness</div><div class=\"answer-line\">Loss of reflexes</div><div class=\"answer-line\">Minimal sensory loss</div><div class=\"answer-line\">Pass 2 of 3</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">LP – raised CSF protein with raised WCC</div><div class=\"answer-line\">Nerve conduction studies – consistent with peripheral demyelination</div><div class=\"answer-line\">Anti-ganglioside antibodies – raised</div><div class=\"answer-line\">(will accept MRI – no spinal cord pathology found)</div><div class=\"answer-line\">(also C. jejuni serology - positive)</div><div class=\"answer-line\">Pass 2 of 6</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Respiratory failure – monitor FVC regularly</td><td>Autonomic dysfunction – cardiac monitoring, regular BP measurement</td></tr><tr><td>Pass 2 of 4</td><td>Total pass 10/19 corrects to <span class=\"answer-source-red\">5/10 </span></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"SAQ Q 23\nA 25 year old man presents with foot pain after falling off a ladder on to his left foot.\nHis Xray is shown.","parts":[{"id":"a","label":"Part A","prompt":"Describe the abnormalities on the Xray. (5 marks)"},{"id":"b","label":"Part B","prompt":"List 2 important early complications of this injury.\n(2 marks)"},{"id":"c","label":"Part C","prompt":"List 5 management steps.\n(5 marks)"}],"propPages":["asset:img3724e095240aa723f7"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Widened space between first and second metatarsals indicating ligamentous disruption (1</div><div class=\"answer-line\">mark) CRITICAL 1 of these 2</div><div class=\"answer-line\">Laterally dislocated base second metatarsal with avulsion fractures (fracture/dislocation) (1 mark)</div><div class=\"answer-line\">Transverse fracture first metatarsal mid-shaft (1 mark)</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Distracted</div><div class=\"answer-line\">Oblique fracture neck 2nd metatarsal ( 1 mark)</div><div class=\"answer-line\">Pass 3 of 5</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Vascular injury – dorsalis pedis</div><div class=\"answer-line\">Foot compartment syndrome</div><div class=\"answer-line\">Pass 2 of 2</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia</div><div class=\"answer-line\">Short leg plaster</div><div class=\"answer-line\">Elevation</div><div class=\"answer-line\">Ice</div><div class=\"answer-line\">Urgent orthopaedic involvement</div><div class=\"answer-line\">Pass 4 of 5</div><div class=\"answer-line\">Total pass 9/12 corrects to <span class=\"answer-source-red\">7.5/10</span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"SAQ Q 24\nYou are the consultant on duty in a tertiary ED during a Saturday evening shift. You have received notification of a mass casualty incident. A grandstand at a local football ground has collapsed. There might be as many as 400 injured people on the scene.","parts":[{"id":"a","label":"Part A","prompt":"List 8 important steps you would take to prepare for managing this situation.\n(8 marks)"},{"id":"b","label":"Part B","prompt":"List 6 problems that you may encounter during the first 24 hours.\n(6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Activate hospital disaster plan</td></tr><tr><td colspan=\"2\">Notify hospital executive team</td></tr><tr><td colspan=\"2\">Call in extra staff – medical / nursing / other</td></tr><tr><td colspan=\"2\">Clear the ED</td></tr><tr><td>-</td><td>Discharge those who can be</td></tr><tr><td>-</td><td>Send pts to the ward who are waiting admission</td></tr><tr><td>-</td><td>Clear the waiting room as well as possible</td></tr><tr><td colspan=\"2\">Create a triage area</td></tr><tr><td colspan=\"2\">Assemble teams</td></tr><tr><td colspan=\"2\">Gather extra resources likely to be required (plaster, antibiotics, analgesia etc)</td></tr><tr><td colspan=\"2\">Ready inpatient teams</td></tr><tr><td>-</td><td>Surgical</td></tr><tr><td>-</td><td>Orthopaedic</td></tr><tr><td>-</td><td>Blood bank</td></tr><tr><td>-</td><td>Anaesthetics</td></tr><tr><td>-</td><td>Theatre staff</td></tr><tr><td>-</td><td>Radiology</td></tr><tr><td colspan=\"2\">(I’m sure there are plenty of other things I couldn’t think of)</td></tr><tr><td colspan=\"2\">Pass 5 of 8</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Staff fatigue</div><div class=\"answer-line\">Staff rotation</div><div class=\"answer-line\">Exhausted stocks eg antibiotics, splints, sutures</div><div class=\"answer-line\">Communication systems overloaded / non-functional</div><div class=\"answer-line\">Overloaded radiology services</div><div class=\"answer-line\">Overloaded pathology services</div><div class=\"answer-line\">Limited access to timely OT</div><div class=\"answer-line\">Pt identification and tracking</div><div class=\"answer-line\">(probably some more)</div><div class=\"answer-line\">Pass 3 of 6</div><div class=\"answer-line\">Total pass 8 of 14 corrects to <span class=\"answer-source-red\">5.5/10 </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"SAQ Q 25\nA 68 year old woman has been brought to your tertiary ED by ambulance. She has had chest pain for\nthe last 3 hours.\nOn arrival, her vital signs are:\n\nGCS\n\nBP\n80/40 mmHg O2 sats 100% 6L O2 via Hudson mask Her ECG is given below.","parts":[{"id":"a","label":"Part A","prompt":"Give the rate, rhythm and axis of the ECG. (3 marks)"},{"id":"b","label":"Part B","prompt":"Give the main pathology identified on the ECG, with evidence. (3 marks)"},{"id":"c","label":"Part C","prompt":"List your treatment steps, including drugs and doses where appropriate. (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">(accelerated) Junctional rhythm, rate 75/min, axis normal</div><div class=\"answer-line\">Pass 3 of 3</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Inferior STEMI – ST elevation II, III, aVF, reciprocal depression lateral leads (I, aVL)</div><div class=\"answer-line\">Probable R sided involvement – STE III&gt;II</div><div class=\"answer-line\">ST depression V1 – V5 – reflects possible posterior involvement or else this too is reciprocal</div><div class=\"answer-line\">Pass 2 of 3</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Fluid load – IV N/S 500mL, aiming for BP &gt;90mmHg</div><div class=\"answer-line\">Analgesia – IV morphine aliquots 2.5mg</div><div class=\"answer-line\">Aspirin 300mg</div><div class=\"answer-line\">Clopidogrel (or other) 300-600mg</div><div class=\"answer-line\">Heparin bolus 4000-5000U</div><div class=\"answer-line\">Urgent consultation with interventional cardiologist to arrange PCI for reperfusion</div><div class=\"answer-line\">(Marking all or nothing ie must have step and dose correct (no ½ marks))</div><div class=\"answer-line\">Pass 4 of 6</div><div class=\"answer-line\">Total pass 9/12 corrects to <span class=\"answer-source-red\">7.5/10 </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"SAQ Q 26\nA 67 year old man has been brought to your ED after being found on the floor of his bedroom with an altered level of consciousness. After initial assessment, you conclude that his altered level of consciousness is due to hyponatremia, with a serum sodium level of 112.","parts":[{"id":"a","label":"Part A","prompt":"List 5 features of collateral history you would like to obtain to help you elucidate the cause\n• f his hyponatremia. Include a reason for each crucial piece of history.\n(5 marks)"},{"id":"b","label":"Part B","prompt":"List 5 investigations you would use to help you elucidate the cause of his hyponatremia.\nInclude the result for which you will be looking. (5 marks) After a short period of time, the patient begins to have a seizure.\nHis vital signs are:\nTemperature 36.0 Pulse 110 /min\n\nBP\n120/85 mmHg O2 sats 98% room air"},{"id":"c","label":"Part C","prompt":"List your 2 initial pharmacological treatment steps. Include doses and end-points.\n(4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Hx organ failure – heart, renal, liver – causes hypervolemic hypoNa</td><td>Drug history – drugs that cause SIADH, diuretics</td></tr><tr><td>Mental health history – drugs that cause SIADH, water intake for psychogenic polydipsia</td><td>Intercurrent illnesses – eg sepsis, pancreatitis, gastroenteritis– causes of hypovolemic hypoNa</td></tr><tr><td>Malignancy – SIADH</td><td>(other things may ne acceptable)</td></tr><tr><td>Pass 3 of 5</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Urea/creat – renal failure</div><div class=\"answer-line\">BSL – cause of dilutional hyponatremia</div><div class=\"answer-line\">TFTs- hypothyroidism</div><div class=\"answer-line\">CXR – lung malignancy – SIADH</div><div class=\"answer-line\">LFTs – liver failure</div><div class=\"answer-line\">Urine Na – elevated in SIADH &gt;20-40</div><div class=\"answer-line\">Serum K – for typical low Na / high K ratio in Addison’s disease</div><div class=\"answer-line\">(1 mark for test plus reason no ½ marks)</div><div class=\"answer-line\">Pass 3 of 5</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Midazolam / diazepam 5mg bolus aiming to terminate seizure, repeat if needed</div><div class=\"answer-line\">3% saline bolus – approx. 2mL/kg bolus aiming for seizure termination and small rise in Na (about 5)</div><div class=\"answer-line\">1 mark for drug, 1 mark for rest</div><div class=\"answer-line\">Pass 2 of 4</div><div class=\"answer-line\">TotAL PASS 8/14 corrects to <span class=\"answer-source-red\">5.5/10 </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"SAQ Q 27\nA 47 year old woman presents to your ED with fever and myalgias. She has a history of lymphoma.","parts":[{"id":"a","label":"Part A","prompt":"List 5 factors will influence your choice of antibiotics. State how each factor will affect your choice. (5 marks)\nHer vital signs are:\n\nGCS\nPulse 135 /min\n\nBP\n75/45 mmHg\n\nRR\n/min O2 sats 98%\n• n room air\n\nTemp\n39.5 degrees Your assessment does not reveal any localising signs for her illness."},{"id":"b","label":"Part B","prompt":"List the escalating steps in her treatment in the ED. Provide doses and end-points where appropriate. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Likely neutropenia based on recent chemo – use local protocol eg pip/taz + gentamicin</div><div class=\"answer-line\">Non neutropenic – Hx and Ex to localise infection for guided treatment</div><div class=\"answer-line\">Presence of infected line – use vancomycin as well</div><div class=\"answer-line\">Pt allergies eg penicillin – use ceftazidime</div><div class=\"answer-line\">Results of Ix – targeted Abs for likely source</div><div class=\"answer-line\">Results of previous Ix – resistant organisms – may need to use different Abs eg meropenem</div><div class=\"answer-line\">Pass 3 of 5</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">End-points are pulse &lt;100, BP &gt;90 systolic, MAP &gt;65mmHg, good end-organ perfusion</div><div class=\"answer-line\">IV fluids – bolus N/S 1000mL, repeat if needed, stop when CVP reaching &gt;12cm H2O (or some</div><div class=\"answer-line\">other reasonable endpoint)</div><div class=\"answer-line\">Insert CVL and arterial line if not-responsive to fluid and need for inotropes</div><div class=\"answer-line\">Noradrenaline infusion start at 5mcg/min via CVL – increase aiming for MAP &gt;65mmHg</div><div class=\"answer-line\">Broad spectrum Abs – pip/taz 4.5g, gentamicin 5-7mg/kg, vancomycin 30mg/kg loading dose</div><div class=\"answer-line\">1 mark for end-points, 1 mark for each step with details (no ½ marks)</div><div class=\"answer-line\">Pass 4 of 5</div><div class=\"answer-line\">Total pass <span class=\"answer-source-red\">7/10 </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":28,"title":"","stemText":"SAQ Q 28\nA 69 year old man has been brought to the ED after an overdose of an unknown quantity of\nquetiapine and diazepam. He was found on the floor of his apartment by his landlord. Due to a reduced level of consciousness, he has been intubated. His blood results are shown:\n\nNa\n136 mmol/L (135 - 145)\n\nK\n8.3 mmol/L (3.5 - 5.1)\n\nCl\n101 mmol/L (100 - 110)\n\nHCO3\nmmol/L (22 - 32)\n\nUrea\nmmol/L (2.9 - 8.2)\n\nCreatinine\n285 umol/L (64 - 108)\n\nGlucose\n7.3 mmol/L (3.0 - 7.8)","parts":[{"id":"a","label":"Part A","prompt":"List the abnormalities on the blood results, giving likely possible causes of each abnormality. (6 marks)"},{"id":"b","label":"Part B","prompt":"What is the most likely clinical scenario responsible for the above blood picture? (2 marks)"},{"id":"c","label":"Part C","prompt":"List your management steps for his hyperkalaemia. Give doses. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Severe hyperkalaemia – cellular shift due to metabolic acidosis, renal failure, cell death with rhabdo</div><div class=\"answer-line\">High anion gap metabolic acidosis – renal failure, lactic acidosis lost likely</div><div class=\"answer-line\">Renal failure – urea/creat less than 100 – suggests intrinsic renal failure – most likely due to rhabdo</div><div class=\"answer-line\">1 mark for each process, 1 mark for explanation (no marks for just saying X is high or Y is low)</div><div class=\"answer-line\">Pass 4 of 6</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Rhabdomyolysis due to prolonged period on floor following sedative overdose</div><div class=\"answer-line\">(accept compartment syndrome)</div><div class=\"answer-line\">1 mark for rhabdo, 1 mark for why</div><div class=\"answer-line\">Pass 1 of 2</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Ca gluconate (membrane stabilisation) – 20mL 10%</td></tr><tr><td colspan=\"2\">Intra-cellular shift</td></tr><tr><td>-</td><td>Serum alkalinisation (hyperventilation and HCO3) aim pH high normal</td></tr><tr><td>-</td><td>Insulin / dextrose – 10U/50mL 50%</td></tr><tr><td>-</td><td>Salbutamol – 5mg nebs via ETT</td></tr><tr><td colspan=\"2\">Removal</td></tr><tr><td>-</td><td>NG resonium 30g</td></tr><tr><td colspan=\"2\">(consider dialysis in refractory cases)</td></tr><tr><td colspan=\"2\">Pass 3 of 4</td></tr><tr><td colspan=\"2\">Total pass 8 of 12 corrects to <span class=\"answer-source-red\">6.5/10</span></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":29,"title":"","stemText":"SAQ Q 29\nA 3 year old boy has been brought to your urban district ED with abdominal pain.\nHis abdominal Xray is shown.","parts":[{"id":"a","label":"Part A","prompt":"Describe the abnormalities on the Xray and give your diagnosis. (2 marks) The patient appears quite distressed and is crying inconsolably. He looks pale.\nHis vital signs are:\nAVPU Alert Pulse 140 /min\n\nBP\n85/45 mmHg\n\nRR\n/min O2 saturations 99% room air"},{"id":"b","label":"Part B","prompt":"List the important details of your management, including disposition. Give doses and end- points where appropriate. (5 marks)"},{"id":"c","label":"Part C","prompt":"List 2 management options for this condition. For each option, outline when it would be\nused. (4 marks) Management option When it would be used"},{"id":"d","label":"Part D","prompt":"List 2 complications of this condition.\n(2 marks)"}],"propPages":["asset:imgbd15cc37c3de0b854a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Dilated loop of large bowel with telescoping segment – intussusception</div><div class=\"answer-line\">Pass 2 of 2 (1 mark for intuss 1 mark for description)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Pass 3 of 5</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Gas insufflation PR – radiological procedure – for uncomplicated cases, first line management</td><td>Surgical correction – for failure of gas reduction, for complicated cases ie perforation</td></tr><tr><td>1 for option 1 mark for when</td><td>Pass 2 of 4</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Perforation / sepsis</div><div class=\"answer-line\">Intestinal ischaemia</div><div class=\"answer-line\">Must have 1 of these , others may be acceptable</div><div class=\"answer-line\">Pass 1 of 2</div><div class=\"answer-line\">Total pass 8 of 13 corrects to <span class=\"answer-source-red\">6/10 </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":30,"title":"","stemText":"SAQ Q 30\nA 12 year old boy has been brought to your ED after falling off a swing and injuring his wrist. The child weighs 40kg. Your assessment has revealed a dorsally angulated fracture of the distal radius. The fracture needs manipulation and placement in a plaster cast. You have decided to perform this procedure in the ED.","parts":[{"id":"a","label":"Part A","prompt":"Give three different methods of procedural sedation for this patient. For each method, give two advantages and two disadvantages. Give doses where appropriate. (15 marks)\nMethod 1\nAdvantages Disadvantages _____________________________________________________________________\nMethod 2"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td><span class=\"answer-source-red\">TOTAL PASS MARK </span></td><td><span class=\"answer-source-red\">189.5/300 </span></td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
